import { useState, useEffect } from 'react';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { 
  WifiOff, 
  Wifi, 
  RefreshCw, 
  CheckCircle, 
  Clock,
  AlertTriangle,
  X
} from 'lucide-react';
import { addSyncListener, getSyncStatus } from '../lib/syncService';
import { getSyncStatistics } from '../lib/database';
import { useLanguage } from '../contexts/LanguageContext';

function OfflineBanner() {
  const { translate: t } = useLanguage();
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [syncInProgress, setSyncInProgress] = useState(false);
  const [pendingItems, setPendingItems] = useState(0);
  const [lastSync, setLastSync] = useState(null);
  const [showBanner, setShowBanner] = useState(false);
  const [bannerType, setBannerType] = useState('offline'); // offline, syncing, success, error
  const [dismissed, setDismissed] = useState(false);

  useEffect(() => {
    // Initialize sync service listener
    const unsubscribe = addSyncListener((syncEvent) => {
      const { event, data, isOnline: online, syncInProgress: inProgress, lastSyncTime } = syncEvent;
      
      setIsOnline(online);
      setSyncInProgress(inProgress);
      
      if (lastSyncTime) {
        setLastSync(lastSyncTime);
      }
      
      // Update banner based on events
      switch (event) {
        case 'offline':
          setBannerType('offline');
          setShowBanner(true);
          setDismissed(false);
          break;
        case 'online':
          setBannerType('online');
          setShowBanner(true);
          setDismissed(false);
          // Auto-hide after 3 seconds
          setTimeout(() => {
            if (!syncInProgress && pendingItems === 0) {
              setShowBanner(false);
            }
          }, 3000);
          break;
        case 'sync-start':
          setBannerType('syncing');
          setShowBanner(true);
          setDismissed(false);
          break;
        case 'sync-success':
          setBannerType('success');
          setShowBanner(true);
          setDismissed(false);
          // Auto-hide after 5 seconds
          setTimeout(() => {
            setShowBanner(false);
          }, 5000);
          break;
        case 'sync-error':
          setBannerType('error');
          setShowBanner(true);
          setDismissed(false);
          break;
      }
    });

    // Initial status check
    const initialStatus = getSyncStatus();
    setIsOnline(initialStatus.isOnline);
    setSyncInProgress(initialStatus.syncInProgress);
    setLastSync(initialStatus.lastSyncTime);

    // Load initial sync statistics
    loadSyncStats();

    // Periodic updates
    const interval = setInterval(loadSyncStats, 30000);

    return () => {
      unsubscribe();
      clearInterval(interval);
    };
  }, []);

  const loadSyncStats = async () => {
    try {
      const stats = await getSyncStatistics();
      const total = (stats.pendingOperations || 0) + (stats.recordsNeedingSync || 0);
      setPendingItems(total);
      
      // Show banner if there are pending items and we're online
      if (total > 0 && isOnline && !dismissed) {
        setShowBanner(true);
        setBannerType('pending');
      }
    } catch (error) {
      console.error('Error loading sync statistics:', error);
    }
  };

  const getBannerConfig = () => {
    switch (bannerType) {
      case 'offline':
        return {
          variant: 'destructive',
          icon: <WifiOff className="h-4 w-4" />,
          title: t('وضع عدم الاتصال'),
          description: t('أنت تعمل حالياً بدون اتصال بالإنترنت. سيتم حفظ تغييراتك محلياً.'),
          showDismiss: false,
          showAction: false
        };
      
      case 'online':
        return {
          variant: 'default',
          icon: <Wifi className="h-4 w-4 text-green-600" />,
          title: t('تم الاتصال بالإنترنت'),
          description: t('تم استعادة الاتصال بالإنترنت. جاري مزامنة البيانات...'),
          showDismiss: true,
          showAction: false
        };
      
      case 'syncing':
        return {
          variant: 'default',
          icon: <RefreshCw className="h-4 w-4 animate-spin text-blue-600" />,
          title: t('جاري المزامنة'),
          description: t(`جاري مزامنة ${pendingItems} عنصر مع الخادم...`),
          showDismiss: false,
          showAction: false
        };
      
      case 'success':
        return {
          variant: 'default',
          icon: <CheckCircle className="h-4 w-4 text-green-600" />,
          title: t('تمت المزامنة بنجاح'),
          description: t('تم مزامنة جميع البيانات بنجاح مع الخادم.'),
          showDismiss: true,
          showAction: false
        };
      
      case 'error':
        return {
          variant: 'destructive',
          icon: <AlertTriangle className="h-4 w-4" />,
          title: t('فشلت المزامنة'),
          description: t('حدث خطأ أثناء مزامنة البيانات. سيتم إعادة المحاولة تلقائياً.'),
          showDismiss: true,
          showAction: true
        };
      
      case 'pending':
        return {
          variant: 'default',
          icon: <Clock className="h-4 w-4 text-orange-600" />,
          title: t('عناصر معلقة للمزامنة'),
          description: t(`يوجد ${pendingItems} عنصر في انتظار المزامنة مع الخادم.`),
          showDismiss: true,
          showAction: true
        };
      
      default:
        return null;
    }
  };

  const handleDismiss = () => {
    setDismissed(true);
    setShowBanner(false);
  };

  const handleRetrySync = async () => {
    try {
      const { syncService } = await import('../lib/syncService');
      await syncService.forceSync();
    } catch (error) {
      console.error('Manual sync failed:', error);
    }
  };

  // Don't show banner if dismissed or not needed
  if (!showBanner || dismissed) {
    return null;
  }

  const config = getBannerConfig();
  if (!config) {
    return null;
  }

  return (
    <div className="fixed top-0 left-0 right-0 z-50 animate-in slide-in-from-top-2">
      <Alert variant={config.variant} className="rounded-none border-x-0 border-t-0">
        <div className="flex items-center justify-between w-full">
          <div className="flex items-center gap-3">
            {config.icon}
            <div className="flex-1">
              <div className="font-medium text-sm">{config.title}</div>
              <AlertDescription className="text-xs mt-1">
                {config.description}
              </AlertDescription>
            </div>
          </div>
          
          <div className="flex items-center gap-2">
            {/* Status badges */}
            {pendingItems > 0 && (
              <Badge variant="secondary" className="text-xs">
                {pendingItems} {t('معلق')}
              </Badge>
            )}
            
            {lastSync && bannerType === 'success' && (
              <Badge variant="outline" className="text-xs">
                {lastSync.toLocaleTimeString('ar-AE')}
              </Badge>
            )}
            
            {/* Action button */}
            {config.showAction && (
              <Button
                size="sm"
                variant="outline"
                onClick={handleRetrySync}
                disabled={syncInProgress}
                className="text-xs h-7"
              >
                <RefreshCw className={`h-3 w-3 mr-1 ${syncInProgress ? 'animate-spin' : ''}`} />
                {t('إعادة المحاولة')}
              </Button>
            )}
            
            {/* Dismiss button */}
            {config.showDismiss && (
              <Button
                size="sm"
                variant="ghost"
                onClick={handleDismiss}
                className="h-7 w-7 p-0"
              >
                <X className="h-3 w-3" />
              </Button>
            )}
          </div>
        </div>
      </Alert>
    </div>
  );
}

export default OfflineBanner;
